mapper.insert:
INSERT IGNORE INTO notifications (
    user_id, refrigerator_item_id, notification_type, title, content,
    expiration_status, reference_date, sent_at
)
SELECT r.user_id, i.item_id, 'EXPIRATION',
       CASE WHEN i.expiration_date < #{referenceDate}
            THEN '유통기한 만료' ELSE '유통기한 임박' END,
       CASE
           WHEN i.expiration_date < #{referenceDate}
               THEN CONCAT(i.item_name, '의 유통기한이 지났습니다. 폐기를 권장합니다.')
           WHEN i.expiration_date = #{referenceDate}
               THEN CONCAT(i.item_name, '의 유통기한이 오늘 만료됩니다.')
           ELSE CONCAT(i.item_name, '가 ', DATEDIFF(i.expiration_date, #{referenceDate}),
                       '일 후 유통기한이 만료됩니다.')
       END,
       CASE WHEN i.expiration_date < #{referenceDate}
            THEN 'EXPIRED' ELSE 'EXPIRING_SOON' END,
       #{referenceDate}, NOW()
FROM refrigerator_items i
JOIN refrigerators r ON r.refrigerator_id = i.refrigerator_id
WHERE i.expiration_date IS NOT NULL
  AND (
      DATEDIFF(i.expiration_date, #{referenceDate}) IN (3, 1)
      OR i.expiration_date < #{referenceDate}
  )
  AND NOT EXISTS (
      SELECT 1
      FROM notifications n
      WHERE n.user_id = r.user_id
        AND n.refrigerator_item_id = i.item_id
        AND n.notification_type = 'EXPIRATION'
        AND (
            (i.expiration_date < #{referenceDate} AND n.expiration_status = 'EXPIRED')
            OR (
                i.expiration_date >= #{referenceDate}
                AND n.expiration_status = 'EXPIRING_SOON'
                AND n.reference_date = #{referenceDate}
            )
        )
  )
